from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const notice=','const heading=','const categoryDefs=','const catName=','function review(','function footer(')))
script=defs+'''
const compact=innerWidth<=1100,cases=[];
for(const language of ['ko','en'])for(const variant of [0,1,2,3,4])for(const stopped of [false,true])for(const width of [656,904,1060]){lang=language;state=initial();state.screen='review';state.stopped=stopped;if(variant===1){state.dbms='PostgreSQL';state.selected=new Set(categoryDefs.map(x=>x.key))}if(variant===2){state.selected=new Set(['objects','data']);state.tables=new Set(['demo.customers','demo.orders'])}if(variant===3){state.selected.clear();state.tables.clear()}if(variant===4){state.source.db='m'.repeat(120);state.target.db='t'.repeat(120)}const f=document.createElement('div');f.className='fixture';f.style.width=width+'px';const id=`${compact?'compact':'wide'}-${language}-${variant}-${stopped}-${width}`;f.innerHTML='<div class="page">'+review()+'</div><footer>'+footer()+'</footer>';f.firstChild.dataset.id=id;cases.push({id,width,viewport:innerWidth,english:language==='en',dbms:state.dbms,sourceDatabase:state.source.db,targetDatabase:state.target.db,categories:[...state.selected],tableCount:state.tables.size,stopped});document.getElementById('fixtures').append(f)}
function read(){return [...document.querySelectorAll('.page')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},foot=e.nextElementSibling;return{id:e.dataset.id,root:box(e),heading:box(e.querySelector('.page-heading')),summary:box(e.querySelector('.summary-list')),notice:e.querySelector('.notice')?box(e.querySelector('.notice')):null,choice:box(e.querySelector('.choice')),disclaimer:box(e.querySelector('.small')),title:e.querySelector('h1').textContent,description:e.querySelector('.page-heading p').textContent,selected:e.querySelector('[data-flag]').checked,summaryValues:[...e.querySelectorAll('.summary-item')].map(x=>x.textContent),footer:{hint:foot.querySelector('.footer-hint').textContent,enabled:!foot.querySelector('[data-action=run]').disabled,label:foot.querySelector('[data-action=run]').textContent.trim()}}})}function getCases(){return cases}
'''
(o/'reviewpage-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'reviewpage-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="reviewpage-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'reviewpage.html').write_text('''<!doctype html><meta charset="utf-8"><title>ReviewPage · original isolation</title><button id="reviewpage-record">Record ReviewPage</button><iframe width="1000" height="950" src="reviewpage-inner.html"></iframe><iframe width="1400" height="950" src="reviewpage-inner.html" style="position:absolute;left:0;top:0;visibility:hidden"></iframe><script>document.getElementById('reviewpage-record').onclick=async()=>{const frames=[...document.querySelectorAll('iframe')];for(const f of frames)await f.contentDocument.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:frames.flatMap(f=>f.contentWindow.read()),cases:frames.flatMap(f=>f.contentWindow.getCases())})});if(!res.ok)throw Error('Record failed');document.getElementById('reviewpage-record').textContent='ReviewPage recorded'}</script>''');print('120 literal Review bodies')
